    const NODE_KINDS = ['sun','mercury','venus','earth','moon','mars','jupiter','saturn','uranus','neptune','dwarf-planet','star','binary-star','comet','asteroid','asteroid-belt','galaxy','nebula','black-hole','satellite','rocket','telescope','orbit','constellation'];
